#include <iostream>
#include <vector>
#include <array>
#include <algorithm>
#include <numeric>
#include <ranges>

int main() {
    using namespace std;
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    unsigned N;
    cin >> N;
    vector<array<unsigned, 3>> P(N);
    for (auto&& [p, a, b] : P)
        cin >> p >> a >> b;

    // テンションは max (P + A) 以下の値を管理する
    const auto M{ranges::max(P | views::transform([](const auto& p) { return p[0] + p[1]; }))};

    // dp[i][j] := i 番目までのプレゼントを受け取ったときのテンションが j のときの、最終的なテンションの値
    vector dp(N + 1, vector<unsigned>(M + 1));

    // すべて受け取り終わったときのテンションが j なら、最終的なテンションは j
    iota(begin(dp.back()), end(dp.back()), 0);

    for (unsigned i = N; i--; ) {
        const auto& [p, a, b] = P[i];
        for (unsigned j = 0; j <= M; ++j)
            // 現在のテンションの値がプレゼントの価値以下なら +A, そうでなければ -B
            dp[i][j] = j <= p ? dp[i + 1][j + a] : dp[i + 1][j - min(j, b)];
    }

    // 大きめのテンションが来たときにいつ範囲内に入るかを判定するため、B の累積和を計算しておく
    vector<unsigned> sum_B(N);
    ranges::copy(P | views::elements<2>, begin(sum_B));
    inclusive_scan(begin(sum_B), end(sum_B), begin(sum_B), plus{});

    // はじめのテンションが x のときの最終的なテンションの値（オフセット込み）
    const auto access{[&dp, &sum_B, N, M](unsigned x) -> unsigned {
        // 最初から範囲内なら、dp の値を返せばよい
        if (x <= M)
            return dp[0][x];

        // 高いなら、しばらく下がり続ける
        const auto need_down{ranges::lower_bound(sum_B, x - M)};
        // N 回下がっても足りないなら、N 回下がるだけ
        if (need_down == end(sum_B))
            return x - sum_B.back();
        // 範囲に入ったら dp の値を返す
        return dp[need_down - begin(sum_B) + 1][x - min(x, *need_down)];
    }};

    unsigned Q;
    cin >> Q;
    for (unsigned i = 0; i < Q; ++i) {
        unsigned x;
        cin >> x;
        cout << access(x) << '\n';
    }
    cout << flush;
    return 0;
}

use proconio::{fastout, input};
use std::{collections::BTreeMap, mem::swap};

#[fastout]
pub fn main() {
    input!(n: usize, pab: [(usize, usize, usize); n], q: usize, x: [usize; q]);
    let mut map = BTreeMap::<usize, Vec<usize>>::new();
    for i in 0..q {
        map.entry(x[i]).or_default().push(i);
    }
    let mut acc = 0;
    let mut stack = vec![];
    for (p, a, b) in pab {
        while let Some((&key, _)) = map.range(..=p + acc).next() {
            let value = map.remove(&key).unwrap();
            stack.push((key.saturating_sub(acc) + acc + a + b, value));
        }
        while let Some((key, mut value)) = stack.pop() {
            map.entry(key)
                .and_modify(|e| {
                    if e.len() < value.len() {
                        swap(e, &mut value);
                    }
                    e.extend(&value);
                })
                .or_insert_with(|| value);
        }
        acc += b;
    }
    let mut ans = vec![0; q];
    for (key, value) in map {
        for i in value {
            ans[i] = key.saturating_sub(acc);
        }
    }
    for ans in ans {
        println!("{ans}");
    }
}
